-- QA-ONLY reference catalog expansion for the Phase 2 full 58-requirement matrix.
-- Adds the CSCC, DCC, TCC, CCC framework rows (ECC already exists on QA from the
-- Phase 1 pilot) and the additional control rows referenced by the approved
-- Requirements & Projects Matrix. All content (title_ar, description_ar, domain_ar,
-- framework metadata) is copied read-only from Production's real catalog -- nothing
-- invented. IDs are assigned fresh by QA's own sequences. Idempotent via WHERE NOT
-- EXISTS guards. QA-only by intent, same as the prior ECC subset migration -- not
-- reviewed for Production application (no unique constraint on controls.control_code).

insert into public.frameworks (code, name_ar, name_en, version, description_ar, is_active)
select 'CSCC', 'ضوابط الأمن السيبراني للأنظمة الحساسة', 'Critical Systems Cybersecurity Controls', '1-2019', 'ضوابط الأمن السيبراني للأنظمة الحساسة الصادرة عن الهيئة الوطنية للأمن السيبراني.', true
where not exists (select 1 from public.frameworks where code = 'CSCC');

insert into public.frameworks (code, name_ar, name_en, version, description_ar, is_active)
select 'DCC', 'ضوابط الأمن السيبراني للبيانات', 'Data Cybersecurity Controls', '1-2022', 'الحد الأدنى من متطلبات الأمن السيبراني لحماية البيانات خلال جميع مراحل دورة حياتها.', true
where not exists (select 1 from public.frameworks where code = 'DCC');

insert into public.frameworks (code, name_ar, name_en, version, description_ar, is_active)
select 'TCC', 'ضوابط الأمن السيبراني للعمل عن بعد', 'Telework Cybersecurity Controls', '1-2021', 'متطلبات تمكين العمل عن بعد بطريقة آمنة والحد من مخاطره السيبرانية.', true
where not exists (select 1 from public.frameworks where code = 'TCC');

insert into public.frameworks (code, name_ar, name_en, version, description_ar, is_active)
select 'CCC', 'ضوابط الأمن السيبراني للحوسبة السحابية', 'Cloud Cybersecurity Controls', '2-2024', 'متطلبات الأمن السيبراني للحوسبة السحابية من منظور مقدمي الخدمات والمشتركين.', true
where not exists (select 1 from public.frameworks where code = 'CCC');

insert into public.controls (framework_id, control_code, title_ar, description_ar, domain_ar, implementation_status, evidence_status, verification_status, audit_frequency)
select f.id, v.control_code, v.title_ar, v.description_ar, v.domain_ar, 'not_started', 'not_uploaded', 'not_verified', 'annual'
from public.frameworks f
cross join (values
  ('1-1-1', 'استراتيجية الأمن السيبراني - 1-1-1', 'يجب تحديد وتوثيق واعتماد إستراتيجية الأمن السيبراني للجهة ودعمها من قبل رئيس الجهة أو من ينيبه (ويشار له في هذه الضوابط باسم "صاحب الصلاحية")، وأن تتماشى الأهداف الإستراتيجية للأمن السيبراني للجهة مع المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'حوكمة الأمن السيبراني'),
  ('1-1-2', 'استراتيجية الأمن السيبراني - 1-1-2', 'يجب العمل على تنفيذ خطة عمل لتطبيق إستراتيجية الأمن السيبراني من قبل الجهة.', 'حوكمة الأمن السيبراني'),
  ('1-1-3', 'استراتيجية الأمن السيبراني - 1-1-3', 'يجب مراجعة إستراتيجية الأمن السيبراني على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', 'حوكمة الأمن السيبراني'),
  ('1-10-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-1', 'يجب تطوير واعتماد برنامج للتوعية بالأمن السيبراني في الجهة من خلال قنوات متعددة دورياً، وذلك لتعزيز الوعي بالأمن السيبراني وتهديداته ومخاطره، وبناء ثقافة إيجابية للأمن السيبراني.', 'حوكمة الأمن السيبراني'),
  ('1-10-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-2', 'يجب تطبيق البرنامج المعتمد للتوعية بالأمن السيبراني في الجهة.', 'حوكمة الأمن السيبراني'),
  ('1-10-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-3', 'يجب أن يغطي برنامج التوعية بالأمن السيبراني كيفية حماية الجهة من أهم المخاطر والتهديدات السيبرانية وما يستجد منها، بما في ذلك: ١-١٠-٣-١ التعامل الآمن مع خدمات البريد الإلكتروني خصوصاً مع رسائل التصيد الإلكتروني. ١-١٠-٣-٢ التعامل الآمن مع الأجهزة المحمولة ووسائط التخزين. ١-١٠-٣-٣ التعامل الآمن مع خدمات تصفح الإنترنت. ١-١٠-٣-٤ التعامل الآمن مع وسائل التواصل الاجتماعي.', 'حوكمة الأمن السيبراني'),
  ('1-10-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-4', 'يجب توفير المهارات المتخصصة والتدريب اللازم للعاملين في المجالات الوظيفية ذات العلاقة المباشرة بالأمن السيبراني في الجهة، وتصنيفها بما يتماشى مع مسؤولياتهم الوظيفية فيما يتعلق بالأمن السيبراني، بما في ذلك: ١-١٠-٤-١ موظفو الإدارة المعنية بالأمن السيبراني. ١-١٠-٤-٢ الموظفون العاملون في تطوير البرامج والتطبيقات والموظفون المشغلون للأصول المعلوماتية والتقنية للجهة. ١-١٠-٤-٣ الوظائف الإشرافية والتنفيذية.', 'حوكمة الأمن السيبراني'),
  ('1-10-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-10-5', 'يجب مراجعة تطبيق برنامج التوعية بالأمن السيبراني في الجهة دورياً.', 'حوكمة الأمن السيبراني'),
  ('1-2-1', 'إدارة الأمن السيبراني - 1-2-1', 'يجب إنشاء إدارة معنية بالأمن السيبراني في الجهة مستقلة عن إدارة تقنية المعلومات والاتصالات (ICT/ IT) (وفقاً للأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤/ ٨/ ١٤٣٨ هـ). ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', 'حوكمة الأمن السيبراني'),
  ('1-2-2', 'إدارة الأمن السيبراني - 1-2-2', 'يجب شغل جميع وظائف الأمن السيبراني من قبل مواطنين متفرغين وذوي كفاءة في مجال الأمن السيبراني.', 'حوكمة الأمن السيبراني'),
  ('1-2-3', 'إدارة الأمن السيبراني - 1-2-3', 'يجب إنشاء لجنة إشرافية للأمن السيبراني بتوجيه من صاحب الصلاحية للجهة لضمان التزام ودعم ومتابعة تطبيق برامج وتشريعات الأمن السيبراني، ويتم تحديد وتوثيق واعتماد أعضاء اللجنة ومسؤولياتها وإطار حوكمة أعمالها على أن يكون رئيس الإدارة المعنية بالأمن السيبراني أحد أعضائها. ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', 'حوكمة الأمن السيبراني'),
  ('1-3-1', 'سياسات وإجراءات الأمن السيبراني - 1-3-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد سياسات وإجراءات الأمن السيبراني وما تشمله من ضوابط ومتطلبات الأمن السيبراني، وتوثيقها واعتمادها من قبل صاحب الصلاحية في الجهة، كما يجب نشرها إلى ذوي العلاقة من العاملين في الجهة والأطراف المعنية بها.', 'حوكمة الأمن السيبراني'),
  ('1-3-2', 'سياسات وإجراءات الأمن السيبراني - 1-3-2', 'يجب على الإدارة المعنية بالأمن السيبراني ضمان تطبيق سياسات وإجراءات الأمن السيبراني في الجهة وما تشمله من ضوابط ومتطلبات.', 'حوكمة الأمن السيبراني'),
  ('1-3-3', 'سياسات وإجراءات الأمن السيبراني - 1-3-3', 'يجب أن تكون سياسات وإجراءات الأمن السيبراني مدعومة بمعايير تقنية أمنية (على سبيل المثال: المعايير التقنية الأمنية لجدار الحماية وقواعد البيانات، وأنظمة التشغيل، إلخ).', 'حوكمة الأمن السيبراني'),
  ('1-3-4', 'سياسات وإجراءات الأمن السيبراني - 1-3-4', 'يجب مراجعة سياسات وإجراءات ومعايير الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', 'حوكمة الأمن السيبراني'),
  ('1-4-1', 'أدوار ومسؤوليات الأمن السيبراني - 1-4-1', 'يجب على صاحب الصلاحية تحديد وتوثيق واعتماد الهيكل التنظيمي للحوكمة والأدوار والمسؤوليات الخاصة بالأمن السيبراني للجهة، وتكليف الأشخاص المعنيين بها، كما يجب تقديم الدعم اللازم لإنفاذ ذلك، مع الأخذ بالاعتبار عدم تعارض المصالح.', 'حوكمة الأمن السيبراني'),
  ('1-4-2', 'أدوار ومسؤوليات الأمن السيبراني - 1-4-2', 'يجب مراجعة أدوار ومسؤوليات الأمن السيبراني في الجهة وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', 'حوكمة الأمن السيبراني'),
  ('1-5-1', 'إدارة مخاطر الأمن السيبراني - 1-5-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد وتوثيق واعتماد منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة. وذلك وفقاً لاعتبارات السرية وتوافر وسلامة الأصول المعلوماتية والتقنية.', 'حوكمة الأمن السيبراني'),
  ('1-5-2', 'إدارة مخاطر الأمن السيبراني - 1-5-2', 'يجب على الإدارة المعنية بالأمن السيبراني تطبيق منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة.', 'حوكمة الأمن السيبراني'),
  ('1-5-3', 'إدارة مخاطر الأمن السيبراني - 1-5-3', 'يجب تنفيذ إجراءات تقييم مخاطر الأمن السيبراني بحد أدنى في الحالات التالية: ١-٥-٣-١ في مرحلة مبكرة من المشاريع التقنية. ١-٥-٣-٢ قبل إجراء تغيير جوهري في البنية التقنية. ١-٥-٣-٣ عند التخطيط للحصول على خدمات طرف خارجي. ١-٥-٣-٤ عند التخطيط وقبل إطلاق منتجات وخدمات تقنية جديدة.', 'حوكمة الأمن السيبراني'),
  ('1-5-4', 'إدارة مخاطر الأمن السيبراني - 1-5-4', 'يجب مراجعة منهجية وإجراءات إدارة مخاطر الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', 'حوكمة الأمن السيبراني'),
  ('1-6-1', 'الأمن السيبراني في إدارة مشاريع المعلومات والتقنية - 1-6-1', 'يجب تضمين متطلبات الأمن السيبراني في منهجية وإجراءات إدارة المشاريع وفي إدارة التغيير على الأصول المعلوماتية والتقنية في الجهة لضمان تحديد مخاطر الأمن السيبراني ومعالجتها كجزء من دورة حياة المشروع التقني، وأن تكون متطلبات الأمن السيبراني جزء أساسي من متطلبات المشاريع التقنية.', 'حوكمة الأمن السيبراني'),
  ('1-6-2', 'الأمن السيبراني في إدارة مشاريع المعلومات والتقنية - 1-6-2', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للجهة بحد أدنى ما يلي: ١-٦-٢-١ تقييم الثغرات ومعالجتها. ١-٦-٢-٢ إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين المشاريع والتغييرات.', 'حوكمة الأمن السيبراني'),
  ('1-6-3', 'الأمن السيبراني في إدارة مشاريع المعلومات والتقنية - 1-6-3', 'يجب أن تغطي متطلبات الأمن السيبراني لمشاريع تطوير التطبيقات والبرمجيات الخاصة للجهة بحد أدنى ما يلي: ١-٦-٣-١ .(Secure Coding Standards) استخدام معايير التطوير الآمن للتطبيقات ١-٦-٣-٢ استخدام مصادر مرخصة وموثوقة لأدوات تطوير التطبيقات والمكتبات الخاصة بها (Libraries). ١-٦-٣-٣ إجراء اختبار للتحقق من مدى استيفاء التطبيقات للمتطلبات الأمنية السيبرانية للجهة. ١-٦-٣-٤ أمن التكامل (Integration) بين التطبيقات. ١-٦-٣-٥ إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين التطبيقات.', 'حوكمة الأمن السيبراني'),
  ('1-6-4', 'الأمن السيبراني في إدارة مشاريع المعلومات والتقنية - 1-6-4', 'يجب مراجعة متطلبات الأمن السيبراني في إدارة المشاريع في الجهة دورياً.', 'حوكمة الأمن السيبراني'),
  ('1-7-1', 'الالتزام بمعايير وأنظمة وتشريعات الأمن السيبراني - 1-7-1', 'في حال وجود اتفاقيات أو التزامات دولية معتمدة محلياً تتضمن متطلبات خاصة بالأمن السيبراني، فيجب على الجهة حصر تلك المتطلبات والالتزام بها.', 'حوكمة الأمن السيبراني'),
  ('1-8-1', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-8-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني دورياً.', 'حوكمة الأمن السيبراني'),
  ('1-8-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-8-2', 'يجب مراجعة وتدقيق تطبيق ضوابط الأمن السيبراني في الجهة، من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني (مثل الإدارة المعنية بالمراجعة في الجهة). على أن تتم المراجعة والتدقيق بشكل مستقل يراعى فيه مبدأ عدم تعارض المصالح، وذلك وفقاً للمعايير العامة المقبولة للمراجعة والتدقيق والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'حوكمة الأمن السيبراني'),
  ('1-8-3', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-8-3', 'يجب توثيق نتائج مراجعة وتدقيق الأمن السيبراني، وعرضها على اللجنة الإشرافية للأمن السيبراني وصاحب الصلاحية. كما يجب أن تشتمل النتائج على نطاق المراجعة والتدقيق، والملاحظات المكتشفة، والتوصيات والإجراءات التصحيحية، وخطة معالجة الملاحظات.', 'حوكمة الأمن السيبراني'),
  ('1-9-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-9-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني المتعلقة بالعاملين قبل توظيفهم وأثناء عملهم وعند انتهاء/إنهاء عملهم في الجهة.', 'حوكمة الأمن السيبراني'),
  ('1-9-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-9-2', 'يجب تطبيق متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة.', 'حوكمة الأمن السيبراني'),
  ('1-9-3', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-9-3', 'يجب أن تغطي متطلبات الأمن السيبراني قبل بدء علاقة العاملين المهنية بالجهة بحد أدنى ما يلي: ١-٩-٣-١ تضمين مسؤوليات الأمن السيبراني وبنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) في عقود العاملين في الجهة (لتشمل خلال وبعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة). ١-٩-٣-٢ إجراء المسح الأمني (Screening or Vetting) للعاملين في وظائف الأمن السيبراني والوظائف التقنية ذات الصلاحيات الهامة والحساسة.', 'حوكمة الأمن السيبراني'),
  ('1-9-4', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-9-4', 'يجب أن تغطي متطلبات الأمن السيبراني خلال علاقة العاملين المهنية بالجهة بحد أدنى ما يلي: ١-٩-٤-١ التوعية بالأمن السيبراني (عند بداية المهنة الوظيفية وخلالها). ١-٩-٤-٢ تطبيق متطلبات الأمن السيبراني والالتزام بها وفقاً لسياسات وإجراءات وعمليات الأمن السيبراني للجهة.', 'حوكمة الأمن السيبراني'),
  ('1-9-5', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-9-5', 'يجب مراجعة وإلغاء الصلاحيات للعاملين مباشرة بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.', 'حوكمة الأمن السيبراني'),
  ('1-9-6', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-9-6', 'يجب مراجعة متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة دورياً.', 'حوكمة الأمن السيبراني'),
  ('2-11-3', 'اختبار الاختراق - 2-11-3', 'يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق بحد أدنى ما يلي: ٢-١١-٣-١ نطاق عمل اختبار الاختراق، ليشمل جميع الخدمات المقدمة خارجياً (عن طريق الإنترنت) ومكوناتها التقنية، ومنها: البنية التحتية، المواقع الإلكترونية، تطبيقات الويب، تطبيقات الهواتف الذكية واللوحية، البريد الإلكتروني والدخول عن بعد. ٢-١١-٣-٢ عمل اختبار الاختراق دورياً.', 'تعزيز الأمن السيبراني'),
  ('2-13-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-13-1', 'يجب تحديد وتوثيق واعتماد متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة.', 'تعزيز الأمن السيبراني'),
  ('2-13-2', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-13-2', 'يجب تطبيق متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة.', 'تعزيز الأمن السيبراني'),
  ('2-13-3', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-13-3', 'يجب أن تغطي متطلبات إدارة حوادث وتهديدات الأمن السيبراني بحد أدنى ما يلي: ٢-١٣-٣-١ وضع خطط الاستجابة للحوادث الأمنية وآليات التصعيد. ٢-١٣-٣-٢ تصنيف حوادث الأمن السيبراني. ٢-١٣-٣-٣ تبليغ الهيئة عند حدوث حادثة أمن سيبراني. ٢-١٣-٣-٤ مشاركة التنبيهات والمعلومات الاستباقية ومؤشرات الاختراق وتقارير حوادث الأمن السيبراني مع الهيئة. ٢-١٣-٣-٥ الحصول على المعلومات الاستباقية (Threat Intelligence) والتعامل معها.', 'تعزيز الأمن السيبراني'),
  ('2-13-4', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-13-4', 'يجب مراجعة تطبيق متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة دورياً.', 'تعزيز الأمن السيبراني'),
  ('2-14-1', 'الأمن المادي - 2-14-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'تعزيز الأمن السيبراني'),
  ('2-14-2', 'الأمن المادي - 2-14-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'تعزيز الأمن السيبراني'),
  ('2-14-3', 'الأمن المادي - 2-14-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب بحد أدنى ما يلي: ٢-١٤-٣-١ الدخول المصرح به للأماكن الحساسة في الجهة (مثل: مركز بيانات الجهة، مركز التعافي من الكوارث، أماكن معالجة المعلومات الحساسة، مركز المراقبة الأمنية، غرف اتصالات الشبكة، مناطق الإمداد الخاصة بالأجهزة والعتاد التقنية، وغيرها). ٢-١٤-٣-٢ سجلات الدخول والمراقبة (CCTV). ٢-١٤-٣-٣ حماية معلومات سجلات الدخول والمراقبة.', 'تعزيز الأمن السيبراني'),
  ('2-14-4', 'الأمن المادي - 2-14-4', 'يجب مراجعة متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب دورياً.', 'تعزيز الأمن السيبراني'),
  ('2-15-1', 'أمن تطبيقات الويب - 2-15-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'تعزيز الأمن السيبراني'),
  ('2-15-2', 'أمن تطبيقات الويب - 2-15-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة.', 'تعزيز الأمن السيبراني'),
  ('2-15-3', 'أمن تطبيقات الويب - 2-15-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة بحد أدنى ما يلي: ٢-١٥-٣-١ .(Web Application Firewall) استخدام جدار الحماية لتطبيقات الويب ٢-١٥-٣-٢ .(Multi-tier Architecture) استخدام مبدأ المعمارية متعددة المستويات ٢-١٥-٣-٣ استخدام بروتوكولات آمنة (مثل بروتوكول HTTPS). ٢-١٥-٣-٤ توضيح سياسة الاستخدام الآمن للمستخدمين. ٢-١٥-٣-٥ التحقق من الهوية على أن يتم تحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات دخول المستخدمين.', 'تعزيز الأمن السيبراني'),
  ('2-15-4', 'أمن تطبيقات الويب - 2-15-4', 'يجب مراجعة متطلبات الأمن السيبراني لحماية تطبيقات الويب للجهة من المخاطر السيبرانية دورياً.', 'تعزيز الأمن السيبراني'),
  ('2-3-3', 'حماية الأنظمة ومرافق معالجة المعلومات - 2-3-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة بحد أدنى ما يلي: ٢-٣-٣-١ الحماية من الفيروسات والبرامج والأنشطة المشبوهة والبرمجيات الضارة (Malware) على أجهزة المستخدمين والخوادم باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة، وإدارتها بشكل آمن. ٢-٣-٣-٢ التقييد الحازم لاستخدام أجهزة وسائط التخزين الخارجية والأمن المتعلق بها. ٢-٣-٣-٣ إدارة حزم التحديثات والإصلاحات للأنظمة والتطبيقات والأجهزة (Patch Management). ٢-٣-٣-٤ مزامنة التوقيت (Clock Synchronization) مركزياً ومن مصدر دقيق وموثوق، ومن هذه المصادر ما توفره الهيئة السعودية للمواصفات والمقاييس والجودة.', 'تعزيز الأمن السيبراني'),
  ('2-4-3', 'حماية البريد الإلكتروني - 2-4-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة بحد أدنى ما يلي: ٢-٤-٣-١ تحليل وتصفية (Filtering) رسائل البريد الإلكتروني (وخصوصاً رسائل التصيّد الإلكتروني "Phishing Emails" والرسائل الإقتحامية "Spam Emails") باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة للبريد الإلكتروني. ٢-٤-٣-٢ التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك للدخول عن بعد والدخول عن طريق صفحة موقع البريد الإلكتروني (Webmail). ٢-٤-٣-٣ النسخ الاحتياطي والأرشفة للبريد الإلكتروني. ٢-٤-٣-٤ الحماية من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن. ٢-٤-٣-٥ توثيق مجال البريد الإلكتروني للجهة باستخدام إطار سياسة المرسل ("Sender Policy Framework "SPF) والبريد المعرّف بمفاتيح النطاق (''Domain Keys Identified Mail "DKIM) وسياسة مصادقة الرسائل والإبلاغ .(Domain Message Authentication Reporting and Conformance "DMARC») عنها', 'تعزيز الأمن السيبراني'),
  ('2-5-3', 'إدارة أمن الشبكات - 2-5-3', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة بحد أدنى ما يلي: ٢-٥-٣-١ العزل والتقسيم المادي أو المنطقي لأجزاء الشبكات بشكل آمن، واللازم للسيطرة على مخاطر الأمن السيبراني ذات العلاقة، باستخدام جدار الحماية (Firewall) ومبدأ الدفاع الأمني متعدد المراحل (Defense-in-Depth). ٢-٥-٣-٢ عزل شبكة بيئة الإنتاج عن شبكات بيئات التطوير والاختبار. ٢-٥-٣-٣ أمن التصفح والاتصال بالإنترنت، ويشمل ذلك التقييد الحازم للمواقع الإلكترونية المشبوهة، ومواقع مشاركة وتخزين الملفات، ومواقع الدخول عن بعد. ٢-٥-٣-٤ أمن الشبكات اللاسلكية وحمايتها باستخدام وسائل آمنة للتحقق من الهوية والتشفير، وعدم ربط الشبكات اللاسلكية بشبكة الجهة الداخلية إلا بناءً على دراسة متكاملة للمخاطر المترتبة على ذلك والتعامل معها بما يضمن حماية الأصول التقنية للجهة. ٢-٥-٣-٥ قيود وإدارة منافذ وبروتوكولات وخدمات الشبكة. ٢-٥-٣-٦ أنظمة الحماية المتقدمة لاكتشاف ومنع الاختراقات (Intrusion Prevention Systems). ٢-٥-٣-٧ أمن نظام أسماء النطاقات (DNS). ٢-٥-٣-٨ حماية قناة تصفح الإنترنت من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن. ٢-٥-٣-٩ الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service Attack "DDoS") للحد من المخاطر السيبرانية الناتجة عن هجمات تعطيل الشبكات.', 'تعزيز الأمن السيبراني'),
  ('2-6-3', 'أمن الأجهزة المحمولة - 2-6-3', 'يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة بحد أدنى ما يلي: ٦-٣-١ - ٢ فصل وتشفير البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD). ٢-٦-٣-٢ الاستخدام المحدد والمقيد بناءً على ما تتطلبه مصلحة أعمال الجهة. ٢-٦-٣-٣ حذف البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD) عند فقدان الأجهزة أو بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة. ٢-٦-٣-٤ التوعية الأمنية للمستخدمين.', 'تعزيز الأمن السيبراني'),
  ('2-7-2', 'حماية البيانات والمعلومات - 2-7-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة، حسب مستوى تصنيفها.', 'تعزيز الأمن السيبراني'),
  ('2-8-3', 'التشفير - 2-8-3', 'يجب أن تغطي متطلبات الأمن السيبراني للتشفير بحد أدنى المتطلبات المذكورة في المعايير الوطنية للتشفير الصادرة من الهيئة، مع تطبيق مستوى التشفير المناسب، وذلك بحسب طبيعة ومستوى حساسية البيانات والأنظمة والشبكات وبناءً على تقييم المخاطر من قبل الجهة وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة، وفقاً لما يلي: ٢-٨-٣-١ معايير أنظمة وحلول التشفير المعتمدة والقيود المطبقة عليها (تقنياً وتنظيمياً). ٢-٨-٣-٢ الإدارة الآمنة لمفاتيح التشفير خلال عمليات دورة حياتها.', 'تعزيز الأمن السيبراني'),
  ('2-9-3', 'إدارة النسخ الاحتياطية والاستعادة - 2-9-3', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية بحد أدنى ما يلي: ٢-٩-٣-١ نطاق النسخ الاحتياطية وشموليتها للأصول المعلوماتية والتقنية الحساسة. ٢-٩-٣-٢ القدرة السريعة على استعادة البيانات والأنظمة بعد التعرض لحوادث الأمن السيبراني. ٢-٩-٣-٣ إجراء فحص دوري لمدى فعالية استعادة النسخ الاحتياطية.', 'تعزيز الأمن السيبراني'),
  ('3-1-3', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-3', 'يجب أن تغطي إدارة استمرارية الأعمال في الجهة بحد أدنى ما يلي: ٣-١-٣-١ التأكد من استمرارية الأنظمة والإجراءات المتعلقة بالأمن السيبراني. ٣-١-٣-٢ وضع خطط الاستجابة لحوادث الأمن السيبراني التي قد تؤثر على استمرارية أعمال الجهة. ٣-١-٣-٣ وضع خطط التعافي من الكوارث (Disaster Recovery Plan).', 'صمود الأمن السيبراني'),
  ('4-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني ضمن العقود والاتفاقيات مع الأطراف الخارجية للجهة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-2', 'يجب أن تغطي متطلبات الأمن السيبراني ضمن العقود والاتفاقيات (مثل اتفاقية مستوى الخدمة SLA) مع الأطراف الخارجية التي قد تتأثر بإصابتها بيانات الجهة أو الخدمات المقدمة لها بحد أدنى ما يلي: ٤-١-٢-١ بنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) والحذف الآمن من قِبَل الطرف الخارجي لبيانات الجهة عند انتهاء الخدمة. ٤-١-٢-٢ إجراءات التواصل في حال حدوث حادثة أمن سيبراني. ٤-١-٢-٣ إلزام الطرف الخارجي بتطبيق متطلبات وسياسات الأمن السيبراني للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-1-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-3', 'يجب أن تغطي متطلبات الأمن السيبراني مع الأطراف الخارجية التي تقدم خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات، أو الخدمات المدارة بحد أدنى ما يلي: ٤-١-٣-١ إجراء تقييم لمخاطر الأمن السيبراني، والتأكد من وجود ما يضمن السيطرة على تلك المخاطر، قبل توقيع العقود والاتفاقيات أو عند تغيير المتطلبات التشريعية والتنظيمية ذات العلاقة. ٤-١-٣-٢ أن تكون مراكز عمليات خدمات الأمن السيبراني المدارة للتشغيل والمراقبة، والتي تستخدم طريقة الوصول عن بعد، موجودة بالكامل داخل المملكة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-1-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-4', 'يجب مراجعة متطلبات الأمن السيبراني مع الأطراف الخارجية دورياً.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-2-1', 'الأمن السيبراني للحوسبة السحابية والاستضافة - 4-2-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-2-2', 'الأمن السيبراني للحوسبة السحابية والاستضافة - 4-2-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة للجهة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-2-3', 'الأمن السيبراني للحوسبة السحابية والاستضافة - 4-2-3', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط ضمن المكونات الرئيسية رقم (١) و (٢) و (٣) والمكون الفرعي رقم (١-٤) الضرورية لحماية بيانات الجهة أو الخدمات المقدمة لها، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة بحد أدنى ما يلي: ٤-٢-٣-١ حماية بيانات الجهة من قبل مقدمي خدمات الحوسبة السحابية والاستضافة بما يتوافق مع مستوى تصنيفها، وإعادتها للجهة (بصيغة قابلة للاستخدام) عند انتهاء الخدمة. ٤-٢-٣-٢ فصل البيئة الخاصة بالجهة (وخصوصاً الخوادم الافتراضية) عن غيرها من البيئات التابعة لجهات أخرى في خدمات الحوسبة السحابية.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('4-2-4', 'الأمن السيبراني للحوسبة السحابية والاستضافة - 4-2-4', 'يجب مراجعة متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة دورياً.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية')
) as v(control_code, title_ar, description_ar, domain_ar)
where f.code = 'ECC'
  and not exists (select 1 from public.controls c where c.framework_id = f.id and c.control_code = v.control_code);

insert into public.controls (framework_id, control_code, title_ar, description_ar, domain_ar, implementation_status, evidence_status, verification_status, audit_frequency)
select f.id, v.control_code, v.title_ar, v.description_ar, v.domain_ar, 'not_started', 'not_uploaded', 'not_verified', 'annual'
from public.frameworks f
cross join (values
  ('1-1-1', 'إستراتيجية الأمن السيبراني - 1-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ١-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تضع إستراتيجية الأمن السيبراني للجهة أولوية لدعم حماية الأنظمة الحساسة الخاصة بالجهة.', 'حوكمة الأمن السيبراني'),
  ('1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي ١-٥ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني'),
  ('1-3-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٦-٢ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للأنظمة الحساسة في جهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني'),
  ('1-3-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٦-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لمشاريع تطوير التطبيقات، والبرمجيات الخاصة بالأنظمة الحساسة للجهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني'),
  ('2-10-1', 'اختبار الاختراق - 2-10-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١١-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق للأنظمة الحساسة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-10-2', 'اختبار الاختراق - 2-10-2', 'رجوعاً للضابط ٢-١١-٣-٢ في الضوابط الأساسية للأمن السيبراني، يجب عمل اختبار الاختراق على الأنظمة الحساسة، كل ستة أشهر؛ على الأقل.', 'تعزيز الأمن السيبراني'),
  ('2-11-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١٢-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني للأنظمة الحساسة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-11-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-2', 'رجوعاً للضابط ٢-١٢-٣-٥ في الضوابط الأساسية للأمن السيبراني، يجب أن لا تقل مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني، على الأنظمة الحساسة عن ١٨ شهراً؛ حسب المتطلبات التشريعية، والتنظيمية، ذات العلاقة.', 'تعزيز الأمن السيبراني'),
  ('2-12-1', 'حماية تطبيقات الويب - 2-12-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١٥-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لحماية تطبيقات الويب الخارجية للأنظمة الحساسة للجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-12-2', 'حماية تطبيقات الويب - 2-12-2', 'رجوعاً للضابط ٢-١٥-٣-٢ في الضوابط الأساسية للأمن السيبراني، يجب استخدام مبدأ المعمارية ذات المستويات المتعددة (Multi-tier Architecture) على أن لا يقل عدد المستويات عن ٣ (3-Tier Architecture).', 'تعزيز الأمن السيبراني'),
  ('2-13-1', 'حماية التطبيقات - 2-13-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية التطبيقات الداخلية الخاصة بالأنظمة الحساسة للجهة من المخاطر السيبرانية.', 'تعزيز الأمن السيبراني'),
  ('2-13-2', 'حماية التطبيقات - 2-13-2', 'يجب تطبيق متطلبات الأمن السيبراني؛ لحماية التطبيقات الداخلية، الخاصة بالأنظمة الحساسة للجهة.', 'تعزيز الأمن السيبراني'),
  ('2-13-3', 'حماية التطبيقات - 2-13-3', 'يجب أن تغطي متطلبات الأمن السيبراني؛ لحماية التطبيقات الداخلية، الخاصة بالأنظمة الحساسة للجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-13-4', 'حماية التطبيقات - 2-13-4', 'مراجعة متطلبات الأمن السيبراني لحماية التطبيقات الداخلية الخاصة بالأنظمة الحساسة للجهة دورياً.', 'تعزيز الأمن السيبراني'),
  ('2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٢-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات للأنظمة الحساسة في الجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط ٢-٢-٣-٥ في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول على الأنظمة الحساسة، مرة واحدة، كل ثلاثة أشهر، على الأقل.', 'تعزيز الأمن السيبراني'),
  ('2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٣-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة الحساسة، وأجهزة معالجة المعلومات الخاصة بها، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-4-1', 'إدارة أمن الشبكات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٥-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الأنظمة الحساسة للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-5-1', 'أمن الأجهزة المحمولة - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٦-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، الخاصة بأمن الأجهزة المحمولة، وأجهزة (BYOD) للجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-6-1', 'حماية البيانات والمعلومات - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٧-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات؛ بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-7-1', 'التشفير - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٨-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-8-1', 'إدارة النسخ الاحتياطية - 2-8-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٩-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-8-2', 'إدارة النسخ الاحتياطية - 2-8-2', 'رجوعاً للضابط ٢-٩-٣-٣ في الضوابط الأساسية للأمن السيبراني، يجب إجراء فحص دوري؛ كل ثلاثة أشهر على الأقل، لتحديد مدى فعالية استعادة النسخ الاحتياطية، الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني'),
  ('2-9-1', 'إدارة الثغرات - 2-9-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١٠-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات للأنظمة الحساسة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-9-2', 'إدارة الثغرات - 2-9-2', 'رجوعاً للضابط ٢-١٠-٣-١ في الضوابط الأساسية للأمن السيبراني، يجب فحص الثغرات واكتشافها على المكونات التقنية، للأنظمة الحساسة، مرة واحدة شهرياً؛ على الأقل.', 'تعزيز الأمن السيبراني'),
  ('3-1-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٣-١-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي إدارة استمرارية الأعمال في الجهة، بحد أدنى؛ ما يلي:', 'صمود الأمن السيبراني'),
  ('4-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ٤-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، المتعلقة بالأطراف الخارجية، بحد أدنى؛ ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية')
) as v(control_code, title_ar, description_ar, domain_ar)
where f.code = 'CSCC'
  and not exists (select 1 from public.controls c where c.framework_id = f.id and c.control_code = v.control_code);

insert into public.controls (framework_id, control_code, title_ar, description_ar, domain_ar, implementation_status, evidence_status, verification_status, audit_frequency)
select f.id, v.control_code, v.title_ar, v.description_ar, v.domain_ar, 'not_started', 'not_uploaded', 'not_verified', 'annual'
from public.frameworks f
cross join (values
  ('1-1-1', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-1-1', 'رجوعًا للضابط ١-٨-١ في الضوابط الأساسية للأمن السيبراني، فإنه يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني للبيانات حسب المدة المحددة لكل مستوى.', 'حوكمة الأمن السيبراني'),
  ('1-1-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-1-2', 'رجوعًا للضابط ١-٨-٢ في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن تتم مراجعة تطبيق ضوابط الأمن السيبراني للبيانات من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني من داخل الجهة حسب المدة المحددة لكل مستوى.', 'حوكمة الأمن السيبراني'),
  ('1-2-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٩-٣ في الضوابط الأساسية للأمن السيبراني يجب أن تغطي متطلبات الأمن السيبراني المتعلق بالموارد البشرية لتشمل خلال وبعد إنتهاء/إنهاء العلاقة الوظيفية في الجهة بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني'),
  ('1-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-١٠-٣ في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المحاور المتعلقة بحماية البيانات، بما في ذلك:', 'حوكمة الأمن السيبراني'),
  ('2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٢-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات، بحد أدنى، ما يلي', 'تعزيز الأمن السيبراني'),
  ('2-1-1-1', 'إدارة هويات الدخول والصلاحيات - 2-1-1-1', 'التقييد الحازم بالسماح للحد الأدنى من العاملين للوصول والاطلاع ومشاركة البيانات بناءً على قوائم صلاحيات مقتصرة على موظفين سعوديين إلا بموجب استثناء من قبل صاحب الصلاحية (رئيس الجهة أو من يفوضه) وعلى أن يتم إعتماد هذه القوائم من قبل صاحب الصلاحية.', 'تعزيز الأمن السيبراني'),
  ('2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-1-2', 'إدارة هويات الدخول وصلاحيات الاطلاع على البيانات باستخدام أنظمة إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).', 'تعزيز الأمن السيبراني'),
  ('2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-1-3', 'بالإضافة للضابط الفرعي ٢-٢-٣-٥ في الضوابط الأساسية للأمن السيبراني، يجب مراجعة قوائم الصلاحيات المعتمدة والصلاحيات المستخدمة للتعامل مع البيانات حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني'),
  ('2-2-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٣-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-2-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1-1', 'تطبيق حزم التحديثات، والإصلاحات الأمنية من وقت إطلاقها للأنظمة المستخدمة للتعامل مع البيانات حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني'),
  ('2-2-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-2-1-3', 'مراجعة وتحصين الإعدادات المصنعية (مثل كلمات المرور الثابتة، والخلفية الافتراضية) للأصول التقنية المستخدمة للتعامل مع البيانات.', 'تعزيز الأمن السيبراني'),
  ('2-3-1', 'أمن الأجهزة المحمولة - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٦-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-3-1-1', 'أمن الأجهزة المحمولة - 2-3-1-1', 'إدارة الأجهزة المحمولة المملوكة للجهة مركزيًا باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management – MDM) وتفعيل خاصية الحذف عن بعد.', 'تعزيز الأمن السيبراني'),
  ('2-3-1-2', 'أمن الأجهزة المحمولة - 2-3-1-2', 'إدارة أجهزة (BYOD) مركزيًا باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management – MDM) وتفعيل خاصية الحذف عن بعد.', 'تعزيز الأمن السيبراني'),
  ('2-4-1', 'حماية البيانات والمعلومات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٧-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بحماية البيانات والمعلومات، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-4-1-1', 'حماية البيانات والمعلومات - 2-4-1-1', 'استخدام خاصية العلامات المائية لترميز كامل الوثيقة عند الإنشاء والتخزين والطباعة وعلى الشاشة وعلى كل نسخة بحيث يكون الرمز يمكن تتبعه على مستوى المستخدم أو الجهاز.', 'تعزيز الأمن السيبراني'),
  ('2-4-1-2', 'حماية البيانات والمعلومات - 2-4-1-2', 'استخدام تقنيات منع تسريب البيانات (Data Leakage Prevention) وتقنيات إدارة الصلاحيات (Rights Management).', 'تعزيز الأمن السيبراني'),
  ('2-4-1-3', 'حماية البيانات والمعلومات - 2-4-1-3', 'حظر استخدام البيانات في أي بيئة غير بيئة الإنتاج (Production Environment) إلا بعد إجراء تقييم للمخاطر وتطبيق ضوابط لحماية تلك البيانات، مثل تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling)>', 'تعزيز الأمن السيبراني'),
  ('2-5-1', 'التشفير - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٨-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير في الجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-5-1-1', 'التشفير - 2-5-1-1', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير عند الإنشاء والتخزين والمشاركة وعلى كامل الاتصال الشبكي المستخدم لنقل البيانات وفقًا للمستوى المتقدم (Advanced) ضمن المعايير الوطنية للتشــــــفير (NCS – 1:2020).', 'تعزيز الأمن السيبراني'),
  ('2-6-1', 'الإتلاف الآمن للبيانات - 2-6-1', 'يجب أن تغطي متطلبات الإتلاف الآمن للبيانات في الجهة بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-6-1-1', 'الإتلاف الآمن للبيانات - 2-6-1-1', 'تحديد التقنيات والأدوات والإجراءات لتنفيذ عمليات الإتلاف الآمن للبيانات حسب مستوى تصنيف البيانات.', 'تعزيز الأمن السيبراني'),
  ('2-6-2', 'الإتلاف الآمن للبيانات - 2-6-2', 'يجب مراجعة تطبيق متطلبات الإتلاف الآمن للبيانات في الجهة حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني'),
  ('2-7-1', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الطابعات والماسحات الضوئية وآلات التصوير في الجهة.', 'تعزيز الأمن السيبراني'),
  ('2-7-2', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-2', 'يجب تطبيق متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير في الجهة.', 'تعزيز الأمن السيبراني'),
  ('2-7-3', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-3', 'يجب أن تغطي متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني'),
  ('2-7-4', 'الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير - 2-7-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني للطابعات والماسحات الضوئية وآلات التصوير في الجهة حسب المدة المحددة لكل مستوى.', 'تعزيز الأمن السيبراني'),
  ('3-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ٤-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني المتعلقة بالأطراف الخارجية، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('3-1-1-6', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1-6', 'إعادة تصنيف البيانات إلى أقل مستوى يحقق الهدف، قبل مشاركتها مع الأطراف الخارجية وذلك باستخدام تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية'),
  ('3-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط الأساسية للأمن السيبراني والضوابط ضمن المكونات الرئيسية رقم (١) و (٢) و (٣) من هذه الوثيقة، يجب أن تغطي متطلبات الأمن السيبراني عند التعامل مع الجهات الاستشارية للمشاريع الاستراتيجية ذات الحساسية العالية على المستوى الوطني بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية')
) as v(control_code, title_ar, description_ar, domain_ar)
where f.code = 'DCC'
  and not exists (select 1 from public.controls c where c.framework_id = f.id and c.control_code = v.control_code);

insert into public.controls (framework_id, control_code, title_ar, description_ar, domain_ar, implementation_status, evidence_status, verification_status, audit_frequency)
select f.id, v.control_code, v.title_ar, v.description_ar, v.domain_ar, 'not_started', 'not_uploaded', 'not_verified', 'annual'
from public.frameworks f
cross join (values
  ('1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1', 'رجوعا للضابط 1-3-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل سياسات وإجراءات الأمن السيبراني ما يأتي:', 'حوكمة الأمن السيبراني'),
  ('1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني'),
  ('1-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-3 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المخاطر والتهديدات السيبرانية للعمل عن بعد والاستخدام الآمن للحد من هذه المخاطر والتهديدات، بما في ذلك:', 'حوكمة الأمن السيبراني'),
  ('1-3-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-4 في الضوابط الأساسية للأمن السيبراني، فإنه يجب تدريب العاملين على المهارات التقنية اللازمة لضمان تطبيق متطلبات وممارسات الأمن السيبراني عند التعامل مع أنظمة العمل عن بعد.', 'حوكمة الأمن السيبراني'),
  ('2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-11-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني للأصول التقنية وأنظمة العمل عن بعد، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-11-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-2', 'رجوعاً للضابط 2-12-3-5 في الضوابط الأساسية للأمن السيبراني، يجب ألا تقل مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني لأنظمة العمل عن بعد عن 12 شهراً؛ حسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تعزيز الأمن السيبراني'),
  ('2-12-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-13-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات للأنظمة المستخدمة في العمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط الفرعي2-2-3-5 في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول والصلاحيات المستخدمة للعمل عن بعد، بحد أدنى مرة واحدة كل سنة.', 'تعزيز الأمن السيبراني'),
  ('2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-3-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية أنظمة العمل عن بعد، وأجهزة المعلومات الخاصة بها، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-4-1', 'إدارة أمن الشبكات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-5-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة للعمل عن بعد، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-5-1', 'أمن الأجهزة المحمولة - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-6-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة للعمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-6-1', 'حماية البيانات والمعلومات - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-7-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات للعمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('2-7-1', 'التشفير - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-8-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني'),
  ('3-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 3-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 4-2-3 في الضوابط الأساسية للأمن السيراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية')
) as v(control_code, title_ar, description_ar, domain_ar)
where f.code = 'TCC'
  and not exists (select 1 from public.controls c where c.framework_id = f.id and c.control_code = v.control_code);

insert into public.controls (framework_id, control_code, title_ar, description_ar, domain_ar, implementation_status, evidence_status, verification_status, audit_frequency)
select f.id, v.control_code, v.title_ar, v.description_ar, v.domain_ar, 'not_started', 'not_uploaded', 'not_verified', 'annual'
from public.frameworks f
cross join (values
  ('1-1-T-1-1', 'أدوار ومسؤوليات الأمن السيبراني (المشترك) - 1-1-T-1-1', 'أدوار الأمن السيبراني، وتكليفات المسؤولية والمحاسبة والاستشارة والتبليغ (RACI) لكل أصحاب العلاقة في خدمات الحوسبة السحابية، بما في ذلك أدوار ومسؤوليات صاحب الصلاحية.', 'حوكمة الأمن السيبراني'),
  ('1-2-T-1', 'إدارة مخاطر الأمن السيبراني (المشترك) - 1-2-T-1', 'يجب أن تتضمن منهجية إدارة مخاطر الأمن السيبراني المذكورة في المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني لدى المشتركين بحد أدنى ما يلي:', 'حوكمة الأمن السيبراني'),
  ('1-3-T-1', 'الالتزام بتشريعات ومعايير وضوابط الأمن السيبراني (المشترك) - 1-3-T-1', 'In addition to the ECC control 1-7-1, the CST legislative and regulatory compliance should include as a minimum with the following requirements:', 'حوكمة الأمن السيبراني'),
  ('1-4-T-1', 'الأمن السيبراني المتعلق بالموارد البشرية (المشترك) - 1-4-T-1', 'In addition to Subcontrols in the ECC control 1-9-3, the following requirements should be covered prior the professional relationship of staff with the CST shall cover, at a minimum:', 'حوكمة الأمن السيبراني'),
  ('2-1-T-1', 'إدارة الأصول (المشترك) - 2-1-T-1', 'In addition to controls in the ECC control 2-1, the CST shall cover the following additional controls for cybersecurity requirements for cybersecurity event logs and monitoring management, as a minimum:', 'تعزيز الأمن السيبراني'),
  ('3-1-T-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال (المشترك) - 3-1-T-1', 'In addition to subcontrols in the ECC control 3-1-3, the CST shall cover the following additional subcontrols for cybersecurity requirements for cybersecurity resilience aspects of business continuity management, as a minimum:', 'صمود الأمن السيبراني')
) as v(control_code, title_ar, description_ar, domain_ar)
where f.code = 'CCC'
  and not exists (select 1 from public.controls c where c.framework_id = f.id and c.control_code = v.control_code);
